import re, time, webbrowser
from pathlib import Path
CREATIONS_DIR = Path.home() / "Documents/NOVA_Creations"
CREATIONS_DIR.mkdir(parents=True, exist_ok=True)
def _safe(n):
    n=re.sub(r'[<>:"|?*]','',n).strip() or f"nova_{int(time.time())}"
    p=CREATIONS_DIR / Path(n).name
    p.parent.mkdir(parents=True, exist_ok=True)
    return p
