def create_file(a):
    p=_safe(a.get("path") or "file.txt"); p.write_text(a.get("content") or "", encoding="utf-8"); return f"File ban gaya: {p}"
def create_portfolio(a):
    name=a.get("name") or ""; role=a.get("role") or "Developer"
    if not name or name.lower() in ["","mera portfolio","portfolio","portfolio banao"]:
        return "Portfolio ke liye batao: 1. Naam? 2. Role? 3. Skills? Ex: Naam Pappu Yadav, role AI Developer, Jaipur"
    html=_premium(name, role); base=re.sub(r'\W+','_',name.lower())[:20]; fname=f"{base}_portfolio_{int(time.time())}.html"; p=_safe(fname); p.write_text(html, encoding="utf-8")
    try: webbrowser.open(f"file:///{p.resolve()}")
    except: pass
    return f"Portfolio ban gaya: {p} ({name} - {role})"
def create_custom_portfolio(a):
    return create_portfolio(a)
def list_creations(a=None):
    files=list(CREATIONS_DIR.glob("*")); return "\n".join(f.name for f in files[:10]) if files else "Empty"
TOOLS={"create_file":create_file,"create_portfolio":create_portfolio,"create_custom_portfolio":create_custom_portfolio,"list_creations":list_creations}
